// recipe: stage-bind
// args: bind=s action=s
// serves: world-fingerprint
// returns: ok, bind, action, key, staged, answered, held, error, detail
//
// Stages one of the game's own binds as held or released on the acceptance channel, so a row can walk the
// way a person walks: the game asks `Input.GetKey(KeyBinds.GetBind("up"))`, and the acceptance channel answers
// that question for any staged `KeyCode` (`InputQueryPatches.AnswerKey`, measured 2026-11-22). The OS route is
// closed on purpose - our windows are never activated, and an OS-level input call needs a foreground window.
//
// ONE LINE, because the evaluator compiles a submission as one top-level expression.
((System.Func<string>)(() => { var bind = {{s:bind}}; var action = {{s:action}}; var findType = new System.Func<string, System.Type>((simpleName) => { var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < assemblies.Length; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == simpleName) { return types[t]; } } } return null; }); var vi = findType("VirtualInput"); var binds = findType("KeyBinds"); if (vi == null) { return "{\"ok\":false,\"error\":\"no-VirtualInput\"}"; } if (binds == null) { return "{\"ok\":false,\"error\":\"no-KeyBinds\"}"; } const System.Reflection.BindingFlags Flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; object key; try { key = binds.GetMethod("GetBind", Flags).Invoke(null, new object[] { bind }); } catch (System.Exception error) { return "{\"ok\":false,\"error\":\"bind-not-resolved\",\"detail\":\"" + error.GetType().Name + ": " + (error.InnerException ?? error).Message.Replace("\\", "/").Replace("\"", "''") + "\"}"; } if (key == null) { return "{\"ok\":false,\"error\":\"bind-not-resolved\",\"detail\":\"" + bind + "\"}"; } var keyCode = (UnityEngine.KeyCode)key; vi.GetMethod("Install", Flags).Invoke(null, new object[] { false }); if (action == "down") { vi.GetMethod("PressKey", Flags).Invoke(null, new object[] { keyCode }); } else if (action == "up") { vi.GetMethod("ReleaseKey", Flags).Invoke(null, new object[] { keyCode }); } else { return "{\"ok\":false,\"error\":\"bad-action\",\"detail\":\"down or up\"}"; } var staged = ((int)vi.GetProperty("StagedKeyCount", Flags).GetValue(null, null)).ToString(System.Globalization.CultureInfo.InvariantCulture); var answered = false; try { var tryAnswer = vi.GetMethod("TryAnswerKey", Flags); if (tryAnswer != null) { var heldQuery = System.Enum.Parse(tryAnswer.GetParameters()[1].ParameterType, "Held"); var boxArgs = new object[] { keyCode, heldQuery, false }; answered = (bool)tryAnswer.Invoke(null, boxArgs) && (bool)boxArgs[2]; } } catch { } var held = UnityEngine.Input.GetKey(keyCode); return "{\"ok\":true,\"bind\":\"" + bind.Replace("\"", "''") + "\",\"action\":\"" + action + "\",\"key\":\"" + keyCode.ToString() + "\",\"staged\":" + staged + ",\"answered\":" + (answered ? "true" : "false") + ",\"held\":" + (held ? "true" : "false") + "}"; }))()
